(function(){
'use strict';
const a=window.VersionCompassExactReleases,v=window.VersionCompassExactView,d=window.SPLUNK_DATA.guidance,g=d.exactReleases,parsed=a.read(location.search,g),s=parsed.state,esc=a.esc,main=document.querySelector('main');
document.body.classList.add('editions-preview','exact-view');document.title='Version Compass | Exact release pilot';document.querySelector('.skip-link').href='#exact-selection';
const options=(rows,current)=>rows.map(([id,label])=>'<option value="'+esc(id)+'"'+(id===current?' selected':'')+'>'+esc(label)+'</option>').join('');
main.innerHTML='<section class="hero"><p class="eyebrow">BOUNDED ENTERPRISE PILOT · 9.4 AND 10.4</p><h1 id="exact-title">Exact releases. <br><span>Follow the evidence.</span></h1><p class="dek">Compare assessed release states, see the changes in between, and trace why a finding applies.</p><p>'+esc(g.boundary)+'</p><p><a href="/?product=platform&platform=enterprise">Open the existing release-line guide →</a></p><div class="report-actions"><button type="button" id="copy-link">Copy link</button><button type="button" id="print-report">Print / PDF</button><span id="share-status" role="status"></span></div></section><section id="exact-examples" class="exact-section"><h2>Explore the bounded evidence</h2><p><a href="/?view=exact-releases&from=9.4.15&to=9.4.16">9.4 branch security fix</a> · <a href="/?view=exact-releases&from=9.4.0&to=10.4.0">Capability removal and TLS conflict</a> · <a href="/?view=exact-releases&component=universal-forwarder&from=10.4.2&to=10.4.3">UF regression and fix</a> · <a href="/?view=exact-releases&from=9.4.2&to=9.4.8">Software change versus documentation</a></p></section><section id="exact-selection" class="exact-section"><h2>Select exact releases</h2><div class="exact-controls"><label>Component<select id="exact-component">'+options([['enterprise','Splunk Enterprise'],['universal-forwarder','Universal Forwarder']],s.component)+'</select></label><label>From<select id="exact-from"></select></label><label>Target<select id="exact-to"></select></label><label>Evidence as of<input id="exact-date" type="date" value="'+esc(s.asOf)+'"></label></div><p>Only assessed catalog entries can be selected. A four-component version retains its full identity; unlisted versions are never rounded.</p></section><aside id="exact-warning" class="exact-warning" role="alert" hidden></aside><div id="exact-content"><section id="exact-results" class="exact-section"><p class="kicker">01 / ENDPOINT STATES</p><h2>Net differences at target</h2><p>Unknown is distinct from unavailable. Conflicting sources remain visible; stale evidence retains its original date.</p><div id="exact-cards"></div></section><section id="exact-timeline" class="exact-section"><p class="kicker">02 / RELEASE HISTORY</p><h2>Release timeline</h2><div id="exact-events"></div></section><section id="exact-route" class="exact-section"><p class="kicker">03 / UPGRADE ROUTE</p><h2>Changes encountered on an upgrade route</h2><p id="exact-path"></p><p>A regression can be encountered on an installed route and fixed at the target. Endpoint differences and route changes answer different questions.</p></section><section id="exact-corrections" class="exact-section"><h2>Documentation corrections</h2><ul id="exact-documentation"></ul><p>Documentation corrections are assessed separately from software changes and do not renew verification dates.</p></section><section id="exact-sources" class="exact-section"><h2>Sources and bounded coverage</h2>'+v.directory()+'<p>Only the named public sections were assessed. Coverage is limited to this assessed set and the listed review dates. No broader historical coverage is promised.</p></section></div><div id="exact-report-slot"></div>';
const get=id=>document.getElementById(id);let result=null;
function selectors(){const rows=g.releases.filter(r=>r.component===s.component).map(r=>[r.version,r.version]);for(const field of ['from','to']){const values=rows.some(([id])=>id===s[field])?rows:[[s[field],s[field]+' (outside pilot)'],...rows];get('exact-'+field).innerHTML=options(values,s[field]);}}
function render(initial=false){let errors=initial?[...parsed.errors]:[];try{if(!errors.length)result=a.compare(g,d.sources,a.input(s));}catch(e){errors.push(e.message);}const invalid=!!errors.length;get('exact-warning').hidden=!invalid;get('exact-content').hidden=invalid;get('print-report').disabled=invalid;get('copy-link').disabled=invalid;get('exact-report-slot').innerHTML='';if(invalid){result=null;get('exact-warning').innerHTML='<h2>This exact-release link needs correction</h2><p>'+errors.map(esc).join('<br>')+'</p><p>Original input: <code>'+esc(location.search)+'</code></p><p>No substitute comparison has been produced.</p><a href="/?view=exact-releases">Open a fresh exact-release comparison</a>';return;}
 get('exact-cards').innerHTML=v.cards(result);get('exact-events').innerHTML=v.timeline(result);get('exact-path').textContent=result.path.reason;get('exact-documentation').innerHTML=v.corrections(s.asOf);get('exact-report-slot').innerHTML=v.report(result);if(!initial)history.replaceState(null,'',a.url(s)+location.hash);
}
selectors();render(true);
for(const field of ['from','to','date'])get('exact-'+field).addEventListener('change',e=>{s[field==='date'?'asOf':field]=e.target.value;render();});
get('exact-component').addEventListener('change',e=>{s.component=e.target.value;s.from=s.component==='enterprise'?'9.4.15':'10.4.2';s.to=s.component==='enterprise'?'10.4.4':'10.4.3';selectors();render();});
get('print-report').addEventListener('click',()=>{if(result)window.print();});
get('copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(new URL(a.url(s)+location.hash,location.origin).href);get('share-status').textContent='Link copied.';}catch{get('share-status').textContent=location.href;}});
window.VersionCompassBuildSnapshot=()=>{if(!result)throw Error('Correct the exact-release selection before exporting');return v.report(result);};
}());
